function parseNumericValue(value){if(value===null||value===undefined||value==='')return null;if(typeof value==='number')return Number.isFinite(value)?value:null;let s=String(value).trim();if(!s)return null;let negative=/^\s*\(.*\)\s*$/.test(s);s=s.replace(/[()\s]/g,'').replace(/[^0-9,.-]/g,'');if(!s||!/[0-9]/.test(s))return null;const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>=0&&dot>=0){if(comma>dot)s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else if(comma>=0){s=s.replace(/\./g,'').replace(',','.')}const n=Number(s);if(!Number.isFinite(n))return null;return negative?-Math.abs(n):n}
