function dashComp(r){let m=String(r?.competencia||'').match(/^(\d{4})-(\d{1,2})$/);if(m){let month=+m[2];if(month>=1&&month<=12)return {y:+m[1],m:month}}let d=dashDate(r?.dataPagamento);return d?{y:d.getFullYear(),m:d.getMonth()+1}:null}
