function dashYears(){let ys=new Set([2025,new Date().getFullYear()]);dashRows().forEach(r=>{let d=dashComp(r);if(d)ys.add(d.y)});return [...ys].sort((a,b)=>b-a)}
function dashMonthValue(y,m,rows){return rows.filter(r=>{let d=dashComp(r);return d&&d.y===y&&d.m===m}).reduce((s,r)=>s+dashAmount(r),0)}
function dashYearRows(y,rows){let now=new Date();return rows.filter(r=>{let d=dashComp(r);if(!d||d.y!==y)return false;if(y===now.getFullYear()&&(d.m>now.getMonth()+1))return false;return true})}
function dashCurrentFilters(rows){let company=S.company,status=S.status,q=String(S.q||'').toLocaleLowerCase('pt-BR').trim();return rows.filter(r=>{if(company&&String(r.empresa||'')!==company)return false;if(status&&String(r.status||'')!==status)return false;if(q&&![r.fncp,r.jiraKey,r.titulo,r.empresa,r.empresaJira,r.tag,r.observacoes,r.identificadorErp].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q)))return false;return true})}
function dashCsv(rows,name){let h=['FNCP','Empresa','Título','Valor','Competência','Vencimento','Pagamento','Status','Forma de pagamento','Identificador ERP','Observações','Jira'],out=[h,...rows.map(r=>[r.fncp||r.jiraKey||'',r.empresa||'',r.titulo||'',dashAmount(r),r.competencia||'',r.dataVencimento||'',r.dataPagamento||'',r.status||'',r.formaPagamento||'',r.identificadorErp||'',r.observacoes||'',r.jiraUrl||''])].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';'));let b=new Blob(['\ufeff'+out.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dashExcel(rows,name){let h=['FNCP','Empresa','Título','Valor','Competência','Vencimento','Pagamento','Status','Forma de pagamento','Identificador ERP','Observações'],body=rows.map(r=>[r.fncp||r.jiraKey||'',r.empresa||'',r.titulo||'',dashAmount(r),r.competencia||'',r.dataVencimento||'',r.dataPagamento||'',r.status||'',r.formaPagamento||'',r.identificadorErp||'',r.observacoes||'']);let table='<table border="1"><tr>'+h.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr>'+body.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</table>';let b=new Blob(['<html><meta charset="utf-8"><body>'+table+'</body></html>'],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name+'.xls';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dashRenderTable(rows){let sorted=[...rows].sort((a,b)=>String(b.jiraUpdated||b.dataPagamento||b.jiraCreated||'').localeCompare(String(a.jiraUpdated||a.dataPagamento||a.jiraCreated||'')));return sorted.length?'<div class="table"><table><tr><th>FNCP</th><th>Empresa</th><th>Título</th><th class="num">Valor</th><th>Vencimento</th><th>Pagamento</th><th>Status</th><th>Jira</th></tr>'+sorted.map(r=>'<tr><td><b>'+esc(r.fncp||r.jiraKey||'—')+'</b></td><td>'+esc(r.empresa||'—')+'</td><td>'+esc(r.titulo||'—')+'</td><td class="num">'+brl(dashAmount(r))+'</td><td>'+esc(r.dataVencimento||'—')+'</td><td>'+esc(r.dataPagamento||'—')+'</td><td>'+esc(r.status||'—')+'</td><td>'+(r.jiraUrl?'<a href="'+esc(r.jiraUrl)+'" target="_blank" rel="noopener">Abrir</a>':'—')+'</td></tr>').join('')+'</table></div>':'<div class="empty">Nenhum lançamento encontrado para o período selecionado.</div>'}
function dashPickMonth(m){S.month=String(m);render()}
function loadDashboardApi(){fetch('/api/fncps',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(x=>{let rows=Array.isArray(x)?x:x?.fncps;if(!Array.isArray(rows))throw Error('Resposta sem lista fncps');DASH_DATA=rows;DASH_API_READY=true;render()}).catch(e=>{console.warn('API FNCP não disponível; usando dados locais.',e.message);render()})}
function dash(){
 let rows=dashRows(),ys=dashYears(),y=ys.includes(+S.year)?+S.year:ys[0],selectedMonth=S.month?+S.month:null,m=selectedMonth?+selectedMonth:new Date().getMonth()+1;
 if(!S.year)S.year=String(y); if(!S.month)S.month=String(m);
 let filtered=dashCurrentFilters(rows),monthRows=selectedMonth?filtered.filter(r=>{let d=dashComp(r);return d&&d.y===y&&d.m===m}):filtered.filter(r=>{let d=dashComp(r);return d&&d.y===y});
 let annual=dashYearRows(y,filtered),annualTotal=annual.reduce((s,r)=>s+dashAmount(r),0),monthTotal=monthRows.reduce((s,r)=>s+dashAmount(r),0);
 let vals=Array.from({length:12},(_,i)=>dashMonthValue(y,i+1,filtered)),mx=Math.max(...vals,1);
 let bars=vals.map((v,i)=>{let h=v?Math.max(3,v/mx*175):0;return `<div class="barcol" onclick="dashPickMonth(${i+1})" style="cursor:pointer" title="${DASH_MONTHS[i]}: ${brl(v)}"><div class="barval">${v?brl(v):'—'}</div><div class="bar ${m===i+1?'selected':''}" style="height:${h}px"></div><div class="barlabel">${DASH_SHORT[i]}</div></div>`}).join('');
 let by={};monthRows.forEach(r=>{let k=String(r.empresa||'Sem empresa').trim()||'Sem empresa';by[k]=(by[k]||0)+dashAmount(r)});
 let statuses=[...new Set(rows.map(r=>String(r.status||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
 let companies=[...new Set(rows.map(r=>String(r.empresa||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
 let now=new Date(),end=y===now.getFullYear()?now.toLocaleDateString('pt-BR'):`31/12/${y}`;
 return `<div class="monthly-dashboard">
 <div class="head"><div><h1>Dashboard Mensal</h1><div class="muted">Acompanhamento financeiro por mês e competência. ${DASH_API_READY?rows.length+' FNCP(s) carregados do Jira.':'Carregando dados do Jira...'}</div></div></div>
 <div class="card filters-monthly"><div class="field"><label>Ano</label><select onchange="S.year=this.value;S.month='';render()">${ys.map(v=>`<option value="${v}" ${v===y?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Mês</label><select onchange="S.month=this.value;render()"><option value="" ${!S.month?'selected':''}>Todos</option>${DASH_MONTHS.map((v,i)=>`<option value="${i+1}" ${i+1===m&&S.month?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Empresa</label><select onchange="S.company=this.value;render()"><option value="">Todas as empresas</option>${companies.map(c=>`<option value="${esc(c)}" ${S.company===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select onchange="S.status=this.value;render()"><option value="">Todos os status</option>${statuses.map(st=>`<option value="${esc(st)}" ${S.status===st?'selected':''}>${esc(st)}</option>`).join('')}</select></div><div class="actions" style="grid-column:1/-1"><button class="btn secondary" onclick="S.q='';S.company='';S.status='';render()">Limpar filtros</button><button class="btn secondary" onclick="dashCsv(monthRows,'FNCP_'+y+(selectedMonth?'_'+String(m).padStart(2,'0'):'_TODOS'))">Exportar CSV</button><button class="btn secondary" onclick="dashExcel(monthRows,'FNCP_'+y+(selectedMonth?'_'+String(m).padStart(2,'0'):'_TODOS'))">Exportar Excel</button></div></div>
 <div class="kpis-monthly"><div class="card kpi"><small>Gasto anual</small><strong>${brl(annualTotal)}</strong><em>01/01/${y} até ${end}</em></div><div class="card kpi"><small>Gasto do mês</small><strong>${brl(monthTotal)}</strong><em>${DASH_MONTHS[m-1]}/${y}</em></div></div>
 <div class="two"><div class="card"><h2>Gasto mensal</h2><div class="muted">Valores gastos em cada mês do ano selecionado.</div><div class="chart"><div class="monthly-bars">${bars}</div></div><div class="note">Clique em uma barra para selecionar o mês e carregar os lançamentos abaixo.</div></div><div class="card"><h2>Gasto por empresa</h2><div class="muted">Valores após aplicar os filtros do mês.</div>${Object.keys(by).length?`<div class="company-list">${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([name,v])=>`<div class="company-row"><span>${esc(name)}</span><b>${brl(v)}</b></div>`).join('')}</div>`:'<div class="empty">Sem dados no mês selecionado.</div>'}</div></div>
 <div class="card"><h2>Lançamentos do mês</h2><div class="muted" style="margin-bottom:10px">${selectedMonth?DASH_MONTHS[m-1]+'/'+y:'Todos os meses de '+y} · ${monthRows.length} lançamento(s)</div>${dashRenderTable(monthRows)}</div>
 </div>`
}
function rrow(p){return`<tr><td>${esc(p.fncp)}</td><td>${esc(cn(p.cid))}</td><td>${esc(tn(p))}</td><td class="num">${brl(p.amt)}</td><td>${dbr(p.pay)}</td><td><span class="badge">${comp(p)}</span></td><td><span class="badge status-${p.st}">${esc(p.st)}</span></td><td><button class="btn small secondary" onclick="detailsP('${p.id}')">Detalhes</button> <button class="btn small secondary" onclick="edit('${p.id}')">Editar</button></td></tr>`}
function form(p={}){let cid=p.cid??'',tid=p.tid??'';return`<div class="row"><div class="field"><label>FNCP *</label><input id="f_fncp" value="${esc(p.fncp||'')}"></div><div class="field"><label>Empresa *</label><select id="f_c" onchange="fillT()"><option value="">Selecione…</option>${CAT.map((c,i)=>companyDeleted(i)?'':`<option value="${i}" ${cid==i?'selected':''}>${esc(c[0])}</option>`).join('')}</select></div><div class="field wide"><label>Título *</label><select id="f_t" data-sel="${tid}"></select></div></div><div class="row"><div class="field"><label>Valor (R$) *</label><input id="f_a" type="number" step="0.01" min="0" value="${p.amt??''}"></div><div class="field"><label>Vencimento</label><input id="f_d" type="date" value="${p.due||''}"></div><div class="field"><label>Pagamento</label><input id="f_p" type="date" value="${p.pay||''}" oninput="cp()"></div><div class="field"><label>Competência</label><input id="f_cp" disabled value="${p.pay?comp(p):'—'}"></div></div><div class="row"><div class="field"><label>Status</label><select id="f_s">${ST.map(s=>`<option ${s==(p.st||'Pendente')?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>TAG/TEG</label><input id="f_g" value="${esc(p.tag||'')}"></div></div><div class="row"><div class="field wide"><label>Observações</label><textarea id="f_o" rows="3">${esc(p.obs||'')}</textarea></div></div>`}
function newF(){if(!requireAuth())return dash();return`<div class="head"><div><h1>Nova FNCP</h1><div class="muted">Cadastre um lançamento.</div></div></div><div class="card"><div class="notice">A competência é automática e usa o <b>mês da data de pagamento</b>.</div>${form()}<div class="actions"><button class="btn" onclick="saveP()">Salvar FNCP</button><button class="btn secondary" onclick="go('dash')">Cancelar</button></div><div id="fm" class="note"></div></div>`}
function fillT(){let c=document.getElementById('f_c'),t=document.getElementById('f_t');if(!c||!t)return;let a=c.value!==''?CAT[+c.value][1].map((x,i)=>({x,i})).filter(o=>!titleDeleted(+c.value,o.i)):[],s=t.dataset.sel||'';t.innerHTML=a.length?a.map(o=>`<option value="${o.i}" ${o.i==s?'selected':''}>${esc(o.x)}</option>`).join(''):'<option value="">Sem títulos ativos cadastrados</option>'}
function cp(){let v=document.getElementById('f_p')?.value,e=document.getElementById('f_cp');if(e)e.value=v?`${v.slice(5,7)}/${v.slice(0,4)}`:'—'}
function read(old={}){let g=id=>document.getElementById(id)?.value.trim()||'',a=+g('f_a');if(!g('f_fncp')||g('f_c')===''||g('f_t')===''||!(a>=0))return null;let pay=g('f_p');return{...old,fncp:g('f_fncp'),cid:+g('f_c'),tid:+g('f_t'),amt:a,due:g('f_d'),pay,cm:pay?+pay.slice(5,7):null,cy:pay?+pay.slice(0,4):null,st:g('f_s'),tag:g('f_g'),obs:g('f_o')}}
function saveP(){if(!requireAuth())return;let p=read();if(!p)return document.getElementById('fm').textContent='Preencha FNCP, empresa, título e valor.';let id=uid(),rec={id,...p,deleted:false};P.push(rec);audit('Criou','FNCP',id,`Criou a FNCP ${p.fncp}`,null,rec);go('dash')}
function detailsP(id){
 const p=P.find(x=>x.id===id); if(!p)return;
 const items=historyItems(id);
 document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>Detalhes da FNCP</h2><button class="close" onclick="closeModal()">×</button></div>
 <div class="grid"><div class="card"><small>FNCP</small><strong>${esc(p.fncp)}</strong></div><div class="card"><small>Valor</small><strong>${brl(p.amt)}</strong></div><div class="card"><small>Competência</small><strong>${esc(comp(p))}</strong></div><div class="card"><small>Status</small><strong>${esc(p.st)}</strong></div></div>
 <div class="row"><div class="field"><label>Empresa</label><input value="${esc(cn(p.cid))}" disabled></div><div class="field"><label>Título</label><input value="${esc(tn(p))}" disabled></div><div class="field"><label>TAG/TEG</label><input value="${esc(p.tag||'')}" disabled></div></div>
 <div class="row"><div class="field"><label>Vencimento</label><input value="${esc(dbr(p.due))}" disabled></div><div class="field"><label>Pagamento</label><input value="${esc(dbr(p.pay))}" disabled></div></div>
 <div class="field"><label>Observações</label><textarea rows="3" disabled>${esc(p.obs||'')}</textarea></div>
 <div class="actions">${isLoggedIn()?`<button class="btn" onclick="edit('${p.id}')">Editar</button>`:''}<button class="btn secondary" onclick="historyModal('${p.id}')">Ver histórico</button>${isAdmin()?`<button class="btn danger" onclick="delP('${p.id}')">Excluir</button>`:''}</div>
 <div class="card"><h2>Histórico da FNCP</h2>${items.length?items.map(a=>auditHtml(a)).join(''):'<div class="empty">Nenhum histórico registrado.</div>'}</div>`;
 document.getElementById('modal').classList.add('show')
}
function edit(id){if(!requireAuth())return;let p=P.find(x=>x.id===id);if(!p)return;editId=id;document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>Editar FNCP</h2><button class="close" onclick="closeModal()">×</button></div>${form(p)}<div class="actions"><button class="btn" onclick="updateP()">Salvar alterações</button><button class="btn secondary" onclick="historyModal('${p.id}')">Histórico</button><button class="btn secondary" onclick="closeModal()">Cancelar</button></div><div id="fm" class="note"></div>`;document.getElementById('modal').classList.add('show');fillT();cp()}
function updateP(){if(!requireAuth())return;let old=P.find(x=>x.id===editId),p=read(old);if(!p)return document.getElementById('fm').textContent='Preencha os campos obrigatórios.';let changes=diffPayment(old,p);P=P.map(x=>x.id===editId?p:x);if(changes.length)audit('Alterou','FNCP',editId,changes.map(c=>`${c.field}: ${fmtVal(c.field==='Valor'?'amt':'',c.before)} → ${fmtVal(c.field==='Valor'?'amt':'',c.after)}`).join(' | '),old,p);else save();closeModal();render()}function closeModal(){editId=null;document.getElementById('modal').classList.remove('show')}
function list(){let q=S.q.toLowerCase(),L=P.filter(p=>{let hit=!p.deleted&&!q||[p.fncp,cn(p.cid),tn(p),brl(p.amt),String(p.amt),p.tag].some(x=>String(x||'').toLowerCase().includes(q));return hit&&(!S.company||p.cid==S.company)&&(!S.status||p.st==S.status)&&(!S.month||String(p.pay||'').slice(0,7)===S.month)}).sort((a,b)=>(b.pay||'').localeCompare(a.pay||''));return`<div class="head"><div><h1>Lançamentos</h1><div class="muted">${L.length} resultado(s).</div></div>${isLoggedIn()?`<button class="btn" onclick="go('new')">+ Nova FNCP</button>`:`<button class="btn secondary" onclick="loginModal()">🔐 Entrar para alterar</button>`}</div><div class="card"><div class="toolbar"><div class="field wide"><label>Pesquisa global — FNCP, valor, empresa, título ou TAG/TEG</label><input value="${esc(S.q)}" oninput="S.q=this.value;render()"></div><div class="field"><label>Competência</label><input type="month" value="${S.month}" onchange="S.month=this.value;render()"></div><div class="field"><label>Status</label><select onchange="S.status=this.value;render()"><option value="">Todos</option>${ST.map(x=>`<option ${S.status==x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Empresa</label><select onchange="S.company=this.value;render()"><option value="">Todas</option>${CAT.map((c,i)=>companyDeleted(i)?'':`<option value="${i}" ${S.company==i?'selected':''}>${esc(c[0])}</option>`).join('')}</select></div></div><div class="actions"><button class="btn secondary" onclick="clearF()">Limpar filtros</button><button class="btn secondary" onclick="csv()">Exportar CSV</button><button class="btn secondary" onclick="excel()">Exportar Excel</button></div></div><div class="card"><div class="table">${L.length?`<table><tr><th>FNCP</th><th>Empresa</th><th>Título</th><th class="num">Valor</th><th>Vencimento</th><th>Pagamento</th><th>Competência</th><th>Status</th><th>TAG/TEG</th><th>Ações</th></tr>${L.map(p=>`<tr><td>${esc(p.fncp)}</td><td>${esc(cn(p.cid))}</td><td>${esc(tn(p))}</td><td class="num">${brl(p.amt)}</td><td>${dbr(p.due)}</td><td>${dbr(p.pay)}</td><td><span class="badge">${comp(p)}</span></td><td><span class="badge status-${p.st}">${esc(p.st)}</span></td><td>${esc(p.tag)||'—'}</td><td><button class="btn small secondary" onclick="detailsP('${p.id}')">Detalhes</button> <button class="btn small secondary" onclick="edit('${p.id}')">Editar</button> <button class="btn small secondary" onclick="historyModal('${p.id}')">Histórico</button> <button class="btn small danger" onclick="delP('${p.id}')">Excluir</button></td></tr>`).join('')}</table>`:'<div class="empty">Nenhum lançamento encontrado.</div>'}</div></div>`}
function clearF(){S.q='';S.company='';S.status='';S.month='';render()}
function delP(id){if(!requireAuth())return;let p=P.find(x=>x.id===id);if(p&&confirm('Excluir '+p.fncp+'? A FNCP poderá ser recuperada no Histórico.')){let before={...p};p.deleted=true;p.deletedAt=new Date().toISOString();p.deletedBy=currentUser();audit('Excluiu','FNCP',id,`Excluiu a FNCP ${p.fncp}. O registro foi movido para o Histórico/Lixeira.`,before,p);render()}}
function restoreP(id){if(!requireAdmin())return;let p=P.find(x=>x.id===id);if(p){let before={...p};p.deleted=false;p.restoredAt=new Date().toISOString();p.restoredBy=currentUser();audit('Recuperou','FNCP',id,`Recuperou a FNCP ${p.fncp}.`,before,p);render()}}
function historyItems(id){return A.filter(a=>a.entity==='FNCP'&&(!id||a.entityId===id)).sort((a,b)=>b.at.localeCompare(a.at))}
function historyModal(id){let p=P.find(x=>x.id===id),items=historyItems(id);document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>Histórico · ${esc(p?.fncp||id)}</h2><button class="close" onclick="closeModal()">×</button></div>${items.length?items.map(a=>auditHtml(a)).join(''):'<div class="empty">Nenhum histórico registrado.</div>'}`;document.getElementById('modal').classList.add('show')}
function auditHtml(a){let d=new Date(a.at).toLocaleString('pt-BR');return `<div class="audit"><div class="meta">${d} · <b>${esc(a.user)}</b> · ${esc(a.action)}</div><div class="change">${esc(a.details||'')}</div></div>`}
function history(){if(!requireAuth())return dash();let q=S.q.toLowerCase(),items=A.filter(a=>{let n=entityName(a.entity,a.entityId);return !q||[a.user,a.action,a.entity,a.details,n].some(x=>String(x||'').toLowerCase().includes(q))}).sort((a,b)=>b.at.localeCompare(a.at));return `<div class="head"><div><h1>Histórico / Auditoria</h1><div class="muted">Todas as alterações, exclusões e recuperações ficam registradas.</div></div><button class="btn secondary" onclick="userModal()">👤 Usuário: ${esc(currentUser())}</button></div><div class="card"><div class="notice"><b>Exclusões são recuperáveis.</b> Nenhuma FNCP é removida definitivamente pela tela normal.</div><div class="field wide"><label>Pesquisar histórico</label><input value="${esc(S.q)}" oninput="S.q=this.value;render()" placeholder="Usuário, FNCP, ação ou alteração..."></div></div><div class="card"><h2>Movimentações (${items.length})</h2>${items.length?items.map(a=>`<div class="audit"><div class="meta">${new Date(a.at).toLocaleString('pt-BR')} · <b>${esc(a.user)}</b> · ${esc(a.action)} · ${esc(a.entity)}</div><div class="change"><b>${esc(entityName(a.entity,a.entityId))}</b> — ${esc(a.details||'')}</div>${a.entity==='FNCP'&&a.action==='Excluiu'&&isAdmin()?`<div class="actions"><button class="btn small" onclick="restoreP('${a.entityId}')">♻️ Recuperar FNCP</button><button class="btn small secondary" onclick="historyModal('${a.entityId}')">Ver histórico</button></div>`:''}${a.entity==='Título'&&a.action==='Excluiu'&&isAdmin()?`<div class="actions"><button class="btn small" onclick="restoreTitle('${a.entityId}')">♻️ Recuperar título</button></div>`:''}${a.entity==='Empresa'&&a.action==='Excluiu'&&isAdmin()?`<div class="actions"><button class="btn small" onclick="restoreCompany('${a.entityId}')">♻️ Recuperar empresa</button></div>`:''}</div>`).join(''):'<div class="empty">Nenhuma movimentação encontrada.</div>'}</div>`}
function trash(){if(!requireAuth())return dash();
 const deletedP=P.filter(p=>p.deleted).sort((a,b)=>(b.deletedAt||'').localeCompare(a.deletedAt||''));
 const deletedC=Object.entries(CD).map(([i,v])=>({i,...v})).sort((a,b)=>(b.deletedAt||'').localeCompare(a.deletedAt||''));
 const deletedT=Object.entries(TD).map(([key,v])=>{let [ci,ti]=key.split(':').map(Number);return {key,ci,ti,...v}}).sort((a,b)=>(b.deletedAt||'').localeCompare(a.deletedAt||''));
 return `<div class="head"><div><h1>Lixeira</h1><div class="muted">Registros excluídos logicamente. Somente o Administrador pode recuperar.</div></div></div>
 <div class="card"><div class="notice"><b>Recuperação restrita:</b> somente o perfil Administrador pode recuperar FNCPs, empresas e títulos.</div>
 <h2>FNCPs excluídas (${deletedP.length})</h2>${deletedP.length?`<div class="table"><table><tr><th>FNCP</th><th>Empresa</th><th>Título</th><th>Excluído por</th><th>Quando</th><th>Ação</th></tr>${deletedP.map(p=>`<tr><td>${esc(p.fncp)}</td><td>${esc(cn(p.cid))}</td><td>${esc(tn(p))}</td><td>${esc(p.deletedBy||'—')}</td><td>${esc(formatDateTime(p.deletedAt))}</td><td>${isAdmin()?`<button class="btn small" onclick="restoreP('${p.id}')">♻️ Recuperar</button>`:'<span class="muted">Somente ADM</span>'}</td></tr>`).join('')}</table></div>`:'<div class="empty">Nenhuma FNCP excluída.</div>'}</div>
 <div class="card"><h2>Empresas excluídas (${deletedC.length})</h2>${deletedC.length?`<div class="table"><table><tr><th>Empresa</th><th>Excluída por</th><th>Quando</th><th>Ação</th></tr>${deletedC.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.deletedBy||'—')}</td><td>${esc(formatDateTime(x.deletedAt))}</td><td>${isAdmin()?`<button class="btn small" onclick="restoreCompany('${x.i}')">♻️ Recuperar</button>`:'<span class="muted">Somente ADM</span>'}</td></tr>`).join('')}</table></div>`:'<div class="empty">Nenhuma empresa excluída.</div>'}</div>
 <div class="card"><h2>Títulos excluídos (${deletedT.length})</h2>${deletedT.length?`<div class="table"><table><tr><th>Título</th><th>Empresa</th><th>Excluído por</th><th>Quando</th><th>Ação</th></tr>${deletedT.map(x=>`<tr><td>${esc(x.name||tn({cid:x.ci,tid:x.ti}))}</td><td>${esc(cn(x.ci))}</td><td>${esc(x.deletedBy||'—')}</td><td>${esc(formatDateTime(x.deletedAt))}</td><td>${isAdmin()?`<button class="btn small" onclick="restoreTitle('${x.key}')">♻️ Recuperar</button>`:'<span class="muted">Somente ADM</span>'}</td></tr>`).join('')}</table></div>`:'<div class="empty">Nenhum título excluído.</div>'}</div>`
}
function reports(){
 if(!requireAuth())return dash();
 let rows=dashRows(),y=+S.year,now=new Date(),annual=dashYearRows(y,rows),vals=Array.from({length:12},(_,i)=>dashMonthValue(y,i+1,rows)),total=annual.reduce((s,r)=>s+dashAmount(r),0);
 let paid=rows.filter(r=>{let d=dashDate(r.dataPagamento);if(!d)return false;let a=new Date(y,0,1),b=y===now.getFullYear()?now:new Date(y,11,31,23,59,59,999);return d>=a&&d<=b}).length;
 let by={};annual.forEach(r=>{let k=String(r.empresa||'Sem empresa');by[k]=(by[k]||0)+dashAmount(r)});let mx=Math.max(...vals,1),end=y===now.getFullYear()?now.toLocaleDateString('pt-BR'):`31/12/${y}`;
 let bars=vals.map((v,i)=>{let h=v?Math.max(4,v/mx*205):2,x=30+i*78,yy=225-h;return `<g><rect class="bar" x="${x}" y="${yy}" width="52" height="${h}" rx="5"><title>${DASH_MONTHS[i]}: ${brl(v)}</title></rect><text x="${x+26}" y="250" text-anchor="middle">${DASH_SHORT[i]}</text>${v?`<text x="${x+26}" y="${yy-6}" text-anchor="middle">${brl(v)}</text>`:''}</g>`}).join('');
 return `<div class="head"><div><h1>Relatórios</h1><div class="muted">Consolidação anual. ${y===now.getFullYear()?'Período: 01/01 até hoje.':'Período: 01/01 até 31/12.'}</div></div><div class="actions"><button class="btn" onclick="dashCsv(annual,'FNCP_Relatorio_'+y)">Exportar CSV</button><button class="btn secondary" onclick="dashExcel(annual,'FNCP_Relatorio_'+y)">Exportar Excel</button></div></div>
 <div class="card"><div class="field" style="max-width:220px"><label>Ano</label><select onchange="S.year=this.value;render()">${dashYears().map(v=>`<option value="${v}" ${v===y?'selected':''}>${v}</option>`).join('')}</select></div></div>
 <div class="grid"><div class="card kpi"><small>Total gasto no ano</small><strong>${brl(total)}</strong><em>01/01/${y} até ${end}</em></div><div class="card kpi"><small>Pagamentos realizados</small><strong>${paid}</strong><em>Registros com data de pagamento no período.</em></div></div>
 <div class="two"><div class="card"><h2>Gasto mensal — ${y}</h2><div class="chart"><svg viewBox="0 0 1000 270" preserveAspectRatio="none">${bars}</svg></div><div class="note">Valores gastos em cada mês do ano selecionado.</div></div><div class="card"><h2>Gasto por empresa</h2>${Object.keys(by).length?`<ul class="list">${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([name,v])=>`<li><span>${esc(name)}</span><b>${brl(v)}</b></li>`).join('')}</ul>`:'<div class="empty">Sem dados no ano selecionado.</div>'}</div></div>`
}
function companiesReadOnly(){return `<div class="head"><div><h1>Empresas e títulos</h1><div class="muted">Consulta de empresas e títulos. Para cadastrar, editar ou excluir, entre no sistema.</div></div><button class="btn secondary" onclick="loginModal()">🔐 Entrar para alterar</button></div><div class="card">${CAT.map((c,i)=>{let removed=companyDeleted(i),active=c[1].filter((_,j)=>!titleDeleted(i,j));return `<details ${removed?'class="deleted-company"':''}><summary>${removed?'<span class="danger-text">Excluída:</span> ':''}${esc(c[0])} <span class="muted">· ${active.length} título(s)</span></summary><div style="padding:10px 0">${active.length?`<ul class="list">${active.map(t=>`<li><span>${esc(t)}</span></li>`).join('')}</ul>`:'<div class="empty">Nenhum título ativo.</div>'}</div></details>`}).join('')}</div>`}
function companies(){if(!isLoggedIn())return companiesReadOnly();return`<div class="head"><div><h1>Empresas e títulos</h1><div class="muted">Cadastro e organização. Empresas e títulos excluídos ficam recuperáveis.</div></div><button class="btn" onclick="companyModal()">+ Nova empresa</button></div><div class="card">${CAT.map((c,i)=>{let removed=companyDeleted(i),l=P.filter(p=>!p.deleted&&p.cid===i),t=l.reduce((a,p)=>a+(+p.amt||0),0),active=c[1].filter((_,j)=>!titleDeleted(i,j)),deleted=c[1].filter((_,j)=>titleDeleted(i,j));return removed?`<details class="deleted-company"><summary><span class="danger-text">Excluída:</span> ${esc(c[0])} <span class="muted">· ${c[1].length} título(s) · ${l.length} lançamento(s)</span></summary><div class="actions">${isAdmin()?`<button class="btn small" onclick="restoreCompany('${i}')">♻️ Recuperar empresa</button>`:''}</div><div class="note danger-text">Esta empresa está excluída e não aparece para novos cadastros.</div></details>`:`<details><summary>${esc(c[0])} <span class="muted">· ${active.length} título(s)${deleted.length?' · '+deleted.length+' excluído(s)':''} · ${l.length} lançamento(s)${l.length?' · '+brl(t):''}</span></summary><div class="actions"><button class="btn small secondary" onclick="companyDetails(${i})">Detalhes</button><button class="btn small secondary" onclick="companyModal(${i})">Editar empresa</button><button class="btn small" onclick="titleModal(${i})">+ Novo título</button></div><ul>${c[1].map((x,j)=>titleDeleted(i,j)?`<li class="deleted-row"><span class="danger-text">Excluído:</span> ${esc(x)} ${isAdmin()?`<button class="btn small secondary" onclick="restoreTitle('${titleKey(i,j)}')">♻️ Recuperar</button>`:''}</li>`:`<li>${esc(x)} <button class="btn small secondary" onclick="titleModal(${i},${j})">Editar</button></li>`).join('')||'<li class="muted">Sem títulos cadastrados.</li>'}</ul></details>`}).join('')}</div>`}
function companyDetails(i){
 if(!CAT[i])return; const c=CAT[i], L=P.filter(p=>!p.deleted&&p.cid===i), total=L.reduce((a,p)=>a+(+p.amt||0),0), byStatus={}; L.forEach(p=>byStatus[p.st]=(byStatus[p.st]||0)+1);
 document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>Ficha da empresa</h2><button class="close" onclick="closeModal()">×</button></div><div class="card"><h2>${esc(c[0])}</h2><div class="grid"><div><small class="muted">Títulos ativos</small><strong>${c[1].filter((_,j)=>!titleDeleted(i,j)).length}</strong></div><div><small class="muted">Lançamentos</small><strong>${L.length}</strong></div><div><small class="muted">Total</small><strong>${brl(total)}</strong></div><div><small class="muted">Pago</small><strong>${byStatus.Pago||0}</strong></div></div></div><div class="card"><h2>Títulos</h2>${c[1].length?`<ul class="list">${c[1].map((t,j)=>`<li><span>${titleDeleted(i,j)?'<span class="danger-text">Excluído:</span> ':''}${esc(t)}</span></li>`).join('')}</ul>`:'<div class="empty">Nenhum título.</div>'}</div><div class="card"><h2>Últimos lançamentos</h2>${L.length?`<div class="table"><table><tr><th>FNCP</th><th>Título</th><th>Valor</th><th>Pagamento</th><th>Status</th></tr>${L.slice().sort((a,b)=>(b.pay||'').localeCompare(a.pay||'')).slice(0,10).map(p=>`<tr><td>${esc(p.fncp)}</td><td>${esc(tn(p))}</td><td>${brl(p.amt)}</td><td>${dbr(p.pay)}</td><td>${esc(p.st)}</td></tr>`).join('')}</table></div>`:'<div class="empty">Nenhum lançamento.</div>'}</div><div class="actions">${isLoggedIn()?`<button class="btn" onclick="companyModal(${i})">Editar empresa</button>`:''}</div>`; document.getElementById('modal').classList.add('show')
}
function companyModal(i=null){if(!requireAuth())return;const editing=i!==null,deleted=editing&&companyDeleted(i);document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>${editing?'Editar empresa':'Nova empresa'}</h2><button type="button" class="close" id="closeCompanyModal">×</button></div><div class="field"><label>Nome *</label><input id="m_name" value="${editing?esc(CAT[i][0]):''}" ${deleted?'disabled':''}></div>${deleted?'<div class="note danger-text">Esta empresa está excluída e pode ser recuperada pelo Histórico ou pela lista de Empresas.</div>':''}<div class="actions">${deleted?`<button type="button" class="btn" id="restoreCompanyBtn">♻️ Recuperar empresa</button>`:`<button type="button" class="btn" id="saveCompanyBtn">Salvar</button>${editing?`<button type="button" class="btn danger" id="excludeCompanyBtn">🗑️ Excluir empresa</button>`:''}`}<button type="button" class="btn secondary" id="cancelCompanyBtn">Cancelar</button></div>`;document.getElementById('modal').classList.add('show');const close=document.getElementById('closeCompanyModal');if(close)close.onclick=()=>closeModal();const cancel=document.getElementById('cancelCompanyBtn');if(cancel)cancel.onclick=()=>closeModal();const saveBtn=document.getElementById('saveCompanyBtn');if(saveBtn)saveBtn.onclick=()=>saveCompany(i);const delBtn=document.getElementById('excludeCompanyBtn');if(delBtn)delBtn.onclick=()=>beginExcludeCompany(i);const restoreBtn=document.getElementById('restoreCompanyBtn');if(restoreBtn)restoreBtn.onclick=()=>restoreCompany(String(i))}
function saveCompany(i){if(!requireAuth())return;let n=document.getElementById('m_name')?.value.trim();if(!n)return;if(i===null){CAT.push([n,[]]);audit('Criou','Empresa',String(CAT.length-1),`Criou a empresa ${n}`)}else{let old=CAT[i][0];CAT[i][0]=n;audit('Alterou','Empresa',String(i),`Nome: ${old} → ${n}`,{name:old},{name:n})}closeModal();render()}
function beginExcludeCompany(i){if(!requireAuth())return;i=Number(i);if(!CAT[i]){alert('Não foi possível identificar esta empresa.');return false}const name=CAT[i][0];document.getElementById('modalBody').innerHTML=`<div class="modalhead"><h2>Confirmar exclusão</h2><button type="button" class="close" id="cancelCompanyDeleteTop">×</button></div><div class="notice" style="background:#fff7ed;color:#9a3412"><b>Você está prestes a excluir:</b><br><strong>${esc(name)}</strong><br><br>Esta empresa ficará oculta para novos cadastros. Os títulos e lançamentos existentes não serão apagados e a empresa poderá ser recuperada depois.</div><div class="actions"><button type="button" class="btn danger" id="confirmExcludeCompanyBtn">🗑️ Sim, excluir empresa</button><button type="button" class="btn secondary" id="cancelCompanyDeleteBtn">Cancelar</button></div>`;const back=()=>companyModal(i);document.getElementById('cancelCompanyDeleteTop').onclick=back;document.getElementById('cancelCompanyDeleteBtn').onclick=back;document.getElementById('confirmExcludeCompanyBtn').onclick=()=>doExcludeCompany(i);return true}
function doExcludeCompany(i){if(!requireAuth())return;i=Number(i);if(!CAT[i])return;const name=CAT[i][0];CD[String(i)]={deletedAt:new Date().toISOString(),deletedBy:currentUser(),name};audit('Excluiu','Empresa',String(i),`Excluiu a empresa ${name}. A empresa permanece recuperável.`,{name},{deleted:true,name});closeModal();render()}
function restoreCompany(key){if(!requireAdmin())return;const i=Number(key);if(!CAT[i])return;const name=CAT[i][0];delete CD[String(i)];audit('Recuperou','Empresa',String(i),`Recuperou a empresa ${name}.`,{deleted:true,name},{deleted:false,name});closeModal();render()}
function titleModal(ci,ti=null){if(!requireAuth())return;
 ci=Number(ci);if(companyDeleted(ci)&&ti===null){alert('Esta empresa está excluída. Recupere a empresa antes de cadastrar um novo título.');return} 
 if(ti!==null)ti=Number(ti);
 const deleted=ti!==null&&titleDeleted(ci,ti);
 const titleValue=ti===null?'':CAT[ci]?.[1]?.[ti]||'';
 pendingTitleDelete=null;
 document.getElementById('modalBody').innerHTML=`
 <div class="modalhead"><h2>${ti===null?'Novo título':'Editar título'}</h2><button type="button" class="close" id="closeModalBtn">×</button></div>
 <p class="muted">Empresa: <b>${esc(CAT[ci]?.[0]||'')}</b></p>
 <div class="field"><label>Título *</label><input id="m_title" value="${esc(titleValue)}" ${deleted?'disabled':''}></div>
 ${ti!==null&&!deleted?`<div class="notice"><b>Excluir título</b><br><span>O título será ocultado dos novos lançamentos, mas continuará guardado para consulta e recuperação. Os lançamentos existentes não serão apagados.</span></div>`:''}
 <div class="actions">
 ${!deleted?`<button type="button" class="btn" id="saveTitleBtn">Salvar</button>`:''}
 ${ti!==null&&!deleted?`<button type="button" class="btn danger" id="excludeTitleBtn">🗑️ Excluir título</button>`:''}
 ${deleted?`<button type="button" class="btn" id="restoreTitleBtn">♻️ Recuperar título</button>`:''}
 <button type="button" class="btn secondary" id="cancelModalBtn">Cancelar</button>
 </div>
 ${deleted?'<div class="note danger-text">Este título está excluído e não aparece para novos lançamentos.</div>':''}`;
 document.getElementById('modal').classList.add('show');
 const closeBtn=document.getElementById('closeModalBtn'); if(closeBtn)closeBtn.onclick=()=>closeModal();
 const cancelBtn=document.getElementById('cancelModalBtn'); if(cancelBtn)cancelBtn.onclick=()=>closeModal();
 const saveBtn=document.getElementById('saveTitleBtn'); if(saveBtn)saveBtn.onclick=()=>saveTitle(ci,ti);
 const delBtn=document.getElementById('excludeTitleBtn'); if(delBtn)delBtn.onclick=()=>beginExcludeTitle(ci,ti);
 const restoreBtn=document.getElementById('restoreTitleBtn'); if(restoreBtn)restoreBtn.onclick=()=>restoreTitle(titleKey(ci,ti));
}
function beginExcludeTitle(ci,ti){if(!requireAuth())return;
 ci=Number(ci);ti=Number(ti);
 const title=CAT[ci]?.[1]?.[ti];
 if(!title){alert('Não foi possível identificar este título.');return false}
 pendingTitleDelete={ci,ti};
 document.getElementById('modalBody').innerHTML=`
 <div class="modalhead"><h2>Confirmar exclusão</h2><button type="button" class="close" id="cancelDeleteTop">×</button></div>
 <div class="notice" style="background:#fff7ed;color:#9a3412">
   <b>Você está prestes a excluir:</b><br>
   <strong>${esc(title)}</strong><br>
   <span>Empresa: ${esc(CAT[ci]?.[0]||'')}</span><br><br>
   O título ficará oculto para novos lançamentos, mas poderá ser recuperado depois.
 </div>
 <div class="actions">
   <button type="button" class="btn danger" id="confirmExcludeTitleBtn">🗑️ Sim, excluir título</button>
   <button type="button" class="btn secondary" id="cancelDeleteBtn">Cancelar</button>
 </div>`;
 const top=document.getElementById('cancelDeleteTop'); if(top)top.onclick=()=>titleModal(ci,ti);
 const cancel=document.getElementById('cancelDeleteBtn'); if(cancel)cancel.onclick=()=>titleModal(ci,ti);
 const confirmBtn=document.getElementById('confirmExcludeTitleBtn'); if(confirmBtn)confirmBtn.onclick=()=>doExcludeTitle();
 return true;
}
function doExcludeTitle(){if(!requireAuth())return;
 if(!pendingTitleDelete)return;
 const {ci,ti}=pendingTitleDelete;
 const title=CAT[ci]?.[1]?.[ti];
 if(!title){pendingTitleDelete=null;closeModal();return}
 TD[titleKey(ci,ti)]={deletedAt:new Date().toISOString(),deletedBy:currentUser(),name:title};
 audit('Excluiu','Título',titleKey(ci,ti),`Excluiu o título ${title} da empresa ${CAT[ci][0]}. O título permanece recuperável.`,{title,company:CAT[ci][0]},{deleted:true});
 pendingTitleDelete=null;
 closeModal();
 render();
}
function excludeTitle(ci,ti){if(!requireAuth())return;return beginExcludeTitle(ci,ti)}
function restoreTitle(key){if(!requireAdmin())return;let raw=String(key),[ci,ti]=raw.split(':').map(Number);if(!CAT[ci]?.[1]?.[ti])return;let title=CAT[ci][1][ti],before={deleted:true,title,company:CAT[ci][0]};delete TD[raw];audit('Recuperou','Título',raw,`Recuperou o título ${title} da empresa ${CAT[ci][0]}.`,before,{deleted:false,title,company:CAT[ci][0]});closeModal();render()}
function excel(){
 const L=P.filter(p=>!p.deleted&&(!S.q||[p.fncp,cn(p.cid),tn(p),brl(p.amt),String(p.amt),p.tag].some(x=>String(x||'').toLowerCase().includes(S.q.toLowerCase()))));
 const rows=[['FNCP','Empresa','Título','Valor','Vencimento','Pagamento','Competência','Status','TAG/TEG','Observações'],...L.map(p=>[p.fncp,cn(p.cid),tn(p),p.amt,dbr(p.due),dbr(p.pay),comp(p),p.st,p.tag||'',p.obs||''])];
 const table='<table border="1">'+rows.map((r,i)=>'<tr>'+r.map(v=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table>';
 const blob=new Blob(['<html><head><meta charset="utf-8"></head><body>'+table+'</body></html>'],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='FNCP_Control.xls';a.click();URL.revokeObjectURL(a.href)
}
function csv(){let L=P.filter(p=>!p.deleted&&(!S.q||[p.fncp,cn(p.cid),tn(p),brl(p.amt),String(p.amt),p.tag].some(x=>String(x||'').toLowerCase().includes(S.q.toLowerCase()))));let h=['FNCP','Empresa','Título','Valor','Vencimento','Pagamento','Competência','Status','TAG/TEG','Observações'],rows=[h,...L.map(p=>[p.fncp,cn(p.cid),tn(p),p.amt,dbr(p.due),dbr(p.pay),comp(p),p.st,p.tag||'',p.obs||''])].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';'));let b=new Blob(['\ufeff'+rows.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='FNCP_Control.csv';a.click();URL.revokeObjectURL(a.href)}
render();applyTheme();loadDashboardApi();

