function initFiscalDashboard(){
 const root=document.getElementById('fiscalWrap'); if(!root||root.dataset.init==='1')return; root.dataset.init='1';
 const $=id=>root.querySelector('#'+id); let all=[];
 const months=[{m:5,n:'Mai'},{m:6,n:'Jun'},{m:7,n:'Jul'},{m:8,n:'Ago'},{m:9,n:'Set'},{m:10,n:'Out'},{m:11,n:'Nov'},{m:12,n:'Dez'},{m:1,n:'Jan'},{m:2,n:'Fev'},{m:3,n:'Mar'},{m:4,n:'Abr'}];
 const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
 const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=x=>parseNumericValue(x);
 function iso(s){if(!s)return null;let m=String(s).match(/^(\d{4}-\d{2}-\d{2})/);return m?m[1]:null}
 function fiscalRange(){let y=+$('fy').value;$('from').value=`${y}-05-01`;$('to').value=`${y+1}-04-30`;renderFiscal()}
 function dateOf(r){let b=$('basis').value;if(b==='competencia'){let c=String(r.competencia||'');return /^\d{4}-\d{2}$/.test(c)?c+'-01':null}return iso(r[b])}
 function load(obj){let a=Array.isArray(obj)?obj:obj?.fncps;if(!Array.isArray(a))throw Error('JSON inválido: lista fncps não encontrada.');all=a;let companies=[...new Set(a.map(x=>String(x.empresa||'').trim()).filter(Boolean))].sort((x,y)=>x.localeCompare(y,'pt-BR'));$('company').innerHTML='<option value="">Todas as empresas</option>'+companies.map(x=>`<option>${safe(x)}</option>`).join('');let statuses=[...new Set(a.map(x=>String(x.status||'').trim()).filter(Boolean))].sort();$('status').innerHTML='<option value="">Todos os status</option>'+statuses.map(x=>`<option>${safe(x)}</option>`).join('');$('loadstatus').textContent=`${a.length} FNCPs carregadas da API`;renderFiscal()}
 function renderFiscal(){if(!all.length)return;let from=$('from').value,to=$('to').value,company=$('company').value,status=$('status').value,q=$('q').value.toLocaleLowerCase('pt-BR').trim();let rec=all.filter(r=>{let d=dateOf(r);if(!d||from&&d<from||to&&d>to)return false;if(company&&String(r.empresa||'')!==company)return false;if(status&&String(r.status||'')!==status)return false;if(q&&![r.fncp,r.jiraKey,r.titulo,r.empresa,r.empresaJira].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q)))return false;return true});let total=rec.reduce((s,r)=>s+(num(r.valor)||0),0),complete=rec.filter(r=>String(r.status||'').toLowerCase()==='completo').reduce((s,r)=>s+(num(r.valor)||0),0);$('total').textContent=money(total);$('totalnote').textContent=`${rec.length} registro(s) filtrados`;$('count').textContent=rec.length.toLocaleString('pt-BR');$('complete').textContent=money(complete);$('missing').textContent=rec.filter(r=>num(r.valor)===null).length;let fy=+$('fy').value,ms=months.map(x=>{let year=x.m>=5?fy:fy+1,key=`${year}-${String(x.m).padStart(2,'0')}`,v=rec.filter(r=>dateOf(r)?.slice(0,7)===key).reduce((s,r)=>s+(num(r.valor)||0),0);return {...x,v}}),max=Math.max(1,...ms.map(x=>x.v));$('chartdesc').textContent=`AF ${fy}–${fy+1} · ${$('basis').selectedOptions[0].textContent}`;$('bars').innerHTML=ms.map(x=>`<div class="barcol"><div class="barval">${x.v?money(x.v):'—'}</div><div class="bar" title="${x.n}: ${money(x.v)}" style="height:${x.v?Math.max(3,x.v/max*175):0}px"></div><div class="barlabel">${x.n}</div></div>`).join('');let sums={};rec.forEach(r=>{let k=String(r.empresa||'').trim()||'OUTROS / não classificada';sums[k]=(sums[k]||0)+(num(r.valor)||0)});let top=Object.entries(sums).sort((a,b)=>b[1]-a[1]).slice(0,8),mx=Math.max(1,...top.map(x=>x[1]));$('companies').innerHTML=top.length?top.map(([k,v])=>`<div class="company"><div>${safe(k)}</div><div class="track"><div class="fill" style="width:${v/mx*100}%"></div></div><strong>${money(v)}</strong></div>`).join(''):'<div class="empty">Nenhum resultado.</div>';rec.sort((a,b)=>(dateOf(b)||'').localeCompare(dateOf(a)||''));$('rows').innerHTML=rec.length?rec.map(r=>{let key=r.jiraKey||r.fncp||'',url=r.jiraUrl||(key?'https://locktonbrasil.atlassian.net/browse/'+encodeURIComponent(key):'#');return `<tr><td><a href="${safe(url)}" target="_blank" rel="noopener">${safe(key)}</a></td><td>${safe(r.empresa||'OUTROS / não classificada')}</td><td title="${safe(r.titulo||'')}">${safe(r.titulo||'')}</td><td>${safe(dateOf(r)||'—')}</td><td>${safe(r.status||'—')}</td><td class="money">${num(r.valor)===null?'—':money(num(r.valor))}</td></tr>`}).join(''):'<tr><td colspan="6" class="empty">Nenhuma FNCP corresponde aos filtros.</td></tr>';$('tableinfo').textContent=`${rec.length} registro(s) · Data: ${$('basis').selectedOptions[0].textContent} · Total: ${money(total)}`}
 $('fy').addEventListener('change',fiscalRange);['basis','from','to','company','status','q'].forEach(id=>$(id).addEventListener(id==='q'?'input':'change',renderFiscal));$('reset').addEventListener('click',()=>{$('company').value='';$('status').value='';$('q').value='';fiscalRange()});
 fetch('/api/fncps').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(load).catch(e=>{$('loadstatus').textContent='Falha ao conectar à API: '+e.message+' (verifique se o servidor está aberto e permite CORS).'});
}
